=== FILE: axil_timer.v ===
`default_nettype none

// axil_timer: 32-bit down-counting timer with one-shot and periodic modes and
// a level interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md following microarchitecture.md.
//
// Register map (word offsets):
//   0x0 CTRL   rw  bit0 EN, bit1 IE, bit2 MODE (0 one-shot, 1 periodic)
//   0x4 LOAD   rw  count length in cycles (0 counts as 1)
//   0x8 COUNT  ro  cycles left; a write gets SLVERR
//   0xC STATUS w1c bit0 EXPIRED
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,

    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,

    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,

    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,

    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,

    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,

    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] IDX_CTRL    = 2'd0;
    localparam [1:0] IDX_LOAD    = 2'd1;
    localparam [1:0] IDX_COUNT   = 2'd2;
    localparam [1:0] IDX_STATUS  = 2'd3;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;

    reg                  rvalid_q;
    reg [31:0]           rdata_q;
    reg [1:0]            rresp_q;

    reg                  en_q;
    reg                  ie_q;
    reg                  mode_q;
    reg                  expired_q;
    reg [31:0]           load_q;
    reg [31:0]           count_q;

    // ------------------------------------------------------------------
    // Write channels (microarchitecture section 1)
    // ------------------------------------------------------------------
    wire awready  = !aw_held && !bvalid_q;
    wire wready   = !w_held  && !bvalid_q;
    wire aw_hs    = s_axil_awvalid && awready;
    wire w_hs     = s_axil_wvalid  && wready;
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    // Mapped: word aligned and below 0x10 (microarchitecture section 3).
    wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                           ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       wr_ok     = wr_mapped && (wr_idx != IDX_COUNT);

    wire wr_ctrl  = do_write && wr_mapped && (wr_idx == IDX_CTRL) && wr_strb[0];
    wire wr_load  = do_write && wr_mapped && (wr_idx == IDX_LOAD);
    wire wr_clear = do_write && wr_mapped && (wr_idx == IDX_STATUS) &&
                    wr_strb[0] && wr_data[0];

    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held   <= 1'b0;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_held    <= 1'b0;
            w_data_q  <= 32'd0;
            w_strb_q  <= 4'd0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
        end else begin
            if (aw_hs) begin
                aw_addr_q <= s_axil_awaddr;
            end
            if (w_hs) begin
                w_data_q <= s_axil_wdata;
                w_strb_q <= s_axil_wstrb;
            end
            if (do_write) begin
                // do_write implies bvalid_q is low: both readies need it.
                aw_held  <= 1'b0;
                w_held   <= 1'b0;
                bvalid_q <= 1'b1;
                bresp_q  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
            end else begin
                if (aw_hs) begin
                    aw_held <= 1'b1;
                end
                if (w_hs) begin
                    w_held <= 1'b1;
                end
                if (bvalid_q && s_axil_bready) begin
                    bvalid_q <= 1'b0;
                end
            end
        end
    end

    // ------------------------------------------------------------------
    // Read channel
    // ------------------------------------------------------------------
    wire arready   = !rvalid_q;
    wire ar_hs     = s_axil_arvalid && arready;
    wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                     ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

    reg [31:0] rd_value;
    always @(*) begin
        case (s_axil_araddr[3:2])
            IDX_CTRL:   rd_value = {29'd0, mode_q, ie_q, en_q};
            IDX_LOAD:   rd_value = load_q;
            IDX_COUNT:  rd_value = count_q;
            IDX_STATUS: rd_value = {31'd0, expired_q};
            default:    rd_value = 32'd0;
        endcase
    end

    always @(posedge aclk) begin
        if (!aresetn) begin
            rvalid_q <= 1'b0;
            rdata_q  <= 32'd0;
            rresp_q  <= RESP_OKAY;
        end else if (ar_hs) begin
            rvalid_q <= 1'b1;
            rdata_q  <= rd_mapped ? rd_value : 32'd0;
            rresp_q  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
        end else if (rvalid_q && s_axil_rready) begin
            rvalid_q <= 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // Timer (microarchitecture section 2); priorities by order below
    // ------------------------------------------------------------------
    wire count_end = en_q && (count_q <= 32'd1);

    reg        en_d;
    reg        ie_d;
    reg        mode_d;
    reg        expired_d;
    reg [31:0] load_d;
    reg [31:0] count_d;

    always @(*) begin
        en_d      = en_q;
        ie_d      = ie_q;
        mode_d    = mode_q;
        expired_d = expired_q;
        load_d    = load_q;
        count_d   = count_q;

        // 1. Count step: decrement, reload or stop.
        if (en_q) begin
            if (count_end) begin
                if (mode_q) begin
                    count_d = load_q;
                end else begin
                    count_d = 32'd0;
                    en_d    = 1'b0;
                end
            end else begin
                count_d = count_q - 32'd1;
            end
        end

        // 2. EXPIRED: clear first, then set, so a count end beats a clear.
        if (wr_clear) begin
            expired_d = 1'b0;
        end
        if (count_end) begin
            expired_d = 1'b1;
        end

        // 3. CTRL write wins for EN and COUNT.
        if (wr_ctrl) begin
            ie_d   = wr_data[1];
            mode_d = wr_data[2];
            if (wr_data[0]) begin
                en_d    = 1'b1;
                count_d = load_q;
            end else begin
                en_d    = 1'b0;
            end
        end

        // 4. LOAD byte merge.
        if (wr_load) begin
            if (wr_strb[0]) load_d[7:0]   = wr_data[7:0];
            if (wr_strb[1]) load_d[15:8]  = wr_data[15:8];
            if (wr_strb[2]) load_d[23:16] = wr_data[23:16];
            if (wr_strb[3]) load_d[31:24] = wr_data[31:24];
        end
    end

    always @(posedge aclk) begin
        if (!aresetn) begin
            en_q      <= 1'b0;
            ie_q      <= 1'b0;
            mode_q    <= 1'b0;
            expired_q <= 1'b0;
            load_q    <= 32'd0;
            count_q   <= 32'd0;
        end else begin
            en_q      <= en_d;
            ie_q      <= ie_d;
            mode_q    <= mode_d;
            expired_q <= expired_d;
            load_q    <= load_d;
            count_q   <= count_d;
        end
    end

    // ------------------------------------------------------------------
    // Outputs (all from flops)
    // ------------------------------------------------------------------
    assign s_axil_awready = awready;
    assign s_axil_wready  = wready;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_arready = arready;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rdata   = rdata_q;
    assign s_axil_rresp   = rresp_q;
    assign irq            = expired_q && ie_q;

`ifdef FORMAL
    // Design-intent invariants (not a proof setup; no .sby is delivered).
    always @(*) begin
        // Both halves are never held at once: the second arrival completes.
        assert (!(aw_held && w_held));
        // No write completes while a write response is still waiting.
        assert (!(do_write && bvalid_q));
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
