// Self-checking testbench for axil_timer.
// Two lanes, ADDR_WIDTH 4 (dut4) and ADDR_WIDTH 8 (dut8), driven from shared
// stimulus; sel8 selects the active lane. Stimulus changes on the falling
// edge; cyc counts rising edges, so at a falling edge cyc is the number of
// the last rising edge.
module axil_timer_tb;

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg     aresetn = 1'b0;
    reg     sel8    = 1'b0;
    integer cyc     = 0;
    always @(posedge clk) cyc <= cyc + 1;

    integer passed = 0;
    integer failed = 0;
    reg [8*64-1:0] nonce;

    // Shared stimulus
    reg [7:0]  awaddr_r  = 8'h00;
    reg        awvalid_r = 1'b0;
    reg [31:0] wdata_r   = 32'd0;
    reg [3:0]  wstrb_r   = 4'd0;
    reg        wvalid_r  = 1'b0;
    reg        bready_r  = 1'b0;
    reg [7:0]  araddr_r  = 8'h00;
    reg        arvalid_r = 1'b0;
    reg        rready_r  = 1'b0;

    wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
    wire [1:0]  bresp4, rresp4;
    wire [31:0] rdata4;
    wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
    wire [1:0]  bresp8, rresp8;
    wire [31:0] rdata8;

    axil_timer #(.ADDR_WIDTH(4)) dut4 (
        .aclk           (clk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr_r[3:0]),
        .s_axil_awvalid (awvalid_r & ~sel8),
        .s_axil_awready (awready4),
        .s_axil_wdata   (wdata_r),
        .s_axil_wstrb   (wstrb_r),
        .s_axil_wvalid  (wvalid_r & ~sel8),
        .s_axil_wready  (wready4),
        .s_axil_bresp   (bresp4),
        .s_axil_bvalid  (bvalid4),
        .s_axil_bready  (bready_r & ~sel8),
        .s_axil_araddr  (araddr_r[3:0]),
        .s_axil_arvalid (arvalid_r & ~sel8),
        .s_axil_arready (arready4),
        .s_axil_rdata   (rdata4),
        .s_axil_rresp   (rresp4),
        .s_axil_rvalid  (rvalid4),
        .s_axil_rready  (rready_r & ~sel8),
        .irq            (irq4)
    );

    axil_timer #(.ADDR_WIDTH(8)) dut8 (
        .aclk           (clk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr_r),
        .s_axil_awvalid (awvalid_r & sel8),
        .s_axil_awready (awready8),
        .s_axil_wdata   (wdata_r),
        .s_axil_wstrb   (wstrb_r),
        .s_axil_wvalid  (wvalid_r & sel8),
        .s_axil_wready  (wready8),
        .s_axil_bresp   (bresp8),
        .s_axil_bvalid  (bvalid8),
        .s_axil_bready  (bready_r & sel8),
        .s_axil_araddr  (araddr_r),
        .s_axil_arvalid (arvalid_r & sel8),
        .s_axil_arready (arready8),
        .s_axil_rdata   (rdata8),
        .s_axil_rresp   (rresp8),
        .s_axil_rvalid  (rvalid8),
        .s_axil_rready  (rready_r & sel8),
        .irq            (irq8)
    );

    wire        awready_m = sel8 ? awready8 : awready4;
    wire        wready_m  = sel8 ? wready8  : wready4;
    wire        bvalid_m  = sel8 ? bvalid8  : bvalid4;
    wire [1:0]  bresp_m   = sel8 ? bresp8   : bresp4;
    wire        arready_m = sel8 ? arready8 : arready4;
    wire        rvalid_m  = sel8 ? rvalid8  : rvalid4;
    wire [31:0] rdata_m   = sel8 ? rdata8   : rdata4;
    wire [1:0]  rresp_m   = sel8 ? rresp8   : rresp4;
    wire        irq_m     = sel8 ? irq8     : irq4;

    // irq monitor: sampled before the edge's updates, so rise_edge is the
    // number of the edge after which irq first went high.
    reg     irq_q     = 1'b0;
    integer rises     = 0;
    integer rise_edge = -1;
    always @(posedge clk) begin
        irq_q <= irq_m;
        if (irq_m && !irq_q) begin
            rises     <= rises + 1;
            rise_edge <= cyc;
        end
    end

    // ------------------------------------------------------------------
    // Checking
    // ------------------------------------------------------------------
    task chk(input [31:0] got, input [31:0] exp, input integer id);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check %0d (ADDR_WIDTH %0d, cycle %0d): got 0x%08h, expected 0x%08h",
                       id, sel8 ? 8 : 4, cyc, got, exp);
            end
        end
    endtask

    task wait_cycles(input integer n);
        begin
            repeat (n) @(negedge clk);
        end
    endtask

    task wait_until(input integer target);
        begin
            if (cyc > target) chk(cyc, target, 2);
            while (cyc < target) @(negedge clk);
        end
    endtask

    task do_reset;
        begin
            aresetn   = 1'b0;
            awvalid_r = 1'b0;
            wvalid_r  = 1'b0;
            arvalid_r = 1'b0;
            bready_r  = 1'b0;
            rready_r  = 1'b0;
            repeat (3) @(negedge clk);
            aresetn = 1'b1;
            @(negedge clk);
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks: called at a falling edge, return at a falling edge.
    // order: 0 AW and W together, 1 AW first, 2 W first.
    // ------------------------------------------------------------------
    reg [1:0]  wr_resp;
    integer    wr_edge;
    reg [31:0] rd_data;
    reg [1:0]  rd_resp;
    integer    rd_edge;

    task axi_write(input [7:0] addr, input [31:0] data, input [3:0] strb,
                   input [1:0] order, input integer bdelay);
        reg aw_done, w_done, p_aw, p_w, hs_aw, hs_w;
        reg [1:0] resp_hold;
        integer t;
        begin
            aw_done  = 1'b0;
            w_done   = 1'b0;
            t        = 0;
            bready_r = 1'b0;
            while (!(aw_done && w_done) && t < 64) begin
                p_aw = !aw_done && ((order != 2'd2) || (w_done && t >= 2));
                p_w  = !w_done  && ((order != 2'd1) || (aw_done && t >= 2));
                awvalid_r = p_aw;
                wvalid_r  = p_w;
                if (p_aw) awaddr_r = addr;
                if (p_w) begin
                    wdata_r = data;
                    wstrb_r = strb;
                end
                hs_aw = p_aw && awready_m;
                hs_w  = p_w  && wready_m;
                @(posedge clk);
                @(negedge clk);
                if (hs_aw) aw_done = 1'b1;
                if (hs_w)  w_done  = 1'b1;
                t = t + 1;
            end
            awvalid_r = 1'b0;
            wvalid_r  = 1'b0;
            if (!(aw_done && w_done)) chk(32'd0, 32'd1, 1);
            wr_edge = cyc;
            // BVALID rises on the edge after the write completes.
            chk({31'd0, bvalid_m}, 32'd1, 3);
            chk({30'd0, awready_m, wready_m}, 32'd0, 4);
            resp_hold = bresp_m;
            repeat (bdelay) begin
                @(posedge clk);
                @(negedge clk);
                chk({31'd0, bvalid_m}, 32'd1, 5);
                chk({30'd0, bresp_m}, {30'd0, resp_hold}, 6);
                chk({30'd0, awready_m, wready_m}, 32'd0, 7);
            end
            wr_resp  = bresp_m;
            bready_r = 1'b1;
            @(posedge clk);
            @(negedge clk);
            bready_r = 1'b0;
            chk({31'd0, bvalid_m}, 32'd0, 8);
        end
    endtask

    task axi_read(input [7:0] addr, input integer rdelay);
        reg hs, done;
        reg [31:0] d_hold;
        reg [1:0]  r_hold;
        integer t;
        begin
            done      = 1'b0;
            t         = 0;
            rready_r  = 1'b0;
            araddr_r  = addr;
            arvalid_r = 1'b1;
            while (!done && t < 64) begin
                hs = arready_m;
                @(posedge clk);
                @(negedge clk);
                if (hs) done = 1'b1;
                t = t + 1;
            end
            arvalid_r = 1'b0;
            if (!done) chk(32'd0, 32'd1, 9);
            rd_edge = cyc;
            chk({31'd0, rvalid_m}, 32'd1, 10);
            chk({31'd0, arready_m}, 32'd0, 11);
            d_hold = rdata_m;
            r_hold = rresp_m;
            repeat (rdelay) begin
                @(posedge clk);
                @(negedge clk);
                chk({31'd0, rvalid_m}, 32'd1, 12);
                chk(rdata_m, d_hold, 13);
                chk({30'd0, rresp_m}, {30'd0, r_hold}, 14);
                chk({31'd0, arready_m}, 32'd0, 15);
            end
            rd_data  = rdata_m;
            rd_resp  = rresp_m;
            rready_r = 1'b1;
            @(posedge clk);
            @(negedge clk);
            rready_r = 1'b0;
            chk({31'd0, rvalid_m}, 32'd0, 16);
        end
    endtask

    task wr_chk(input [7:0] addr, input [31:0] data, input [3:0] strb,
                input [1:0] exp_resp, input integer id);
        begin
            axi_write(addr, data, strb, 2'd0, 0);
            chk({30'd0, wr_resp}, {30'd0, exp_resp}, id);
        end
    endtask

    task rd_chk(input [7:0] addr, input [31:0] exp, input [1:0] exp_resp,
                input integer id);
        begin
            axi_read(addr, 0);
            chk(rd_data, exp, id);
            chk({30'd0, rd_resp}, {30'd0, exp_resp}, id);
        end
    endtask

    // ------------------------------------------------------------------
    // The test sequence, run once per lane
    // ------------------------------------------------------------------
    task run_all;
        integer e, base, er, es, cnt;
        begin
            // Reset values
            do_reset;
            chk({31'd0, awready_m}, 32'd1, 20);
            chk({31'd0, wready_m},  32'd1, 21);
            chk({31'd0, arready_m}, 32'd1, 22);
            chk({31'd0, bvalid_m},  32'd0, 23);
            chk({31'd0, rvalid_m},  32'd0, 24);
            chk({31'd0, irq_m},     32'd0, 25);
            rd_chk(8'h0, 32'd0, OKAY, 26);
            rd_chk(8'h4, 32'd0, OKAY, 27);
            rd_chk(8'h8, 32'd0, OKAY, 28);
            rd_chk(8'hC, 32'd0, OKAY, 29);

            // LOAD byte strobes, channel orders, back-pressure
            axi_write(8'h4, 32'h11223344, 4'hF, 2'd0, 0);
            chk({30'd0, wr_resp}, {30'd0, OKAY}, 30);
            rd_chk(8'h4, 32'h11223344, OKAY, 31);
            axi_write(8'h4, 32'hAABBCCDD, 4'b0101, 2'd1, 3);
            chk({30'd0, wr_resp}, {30'd0, OKAY}, 32);
            rd_chk(8'h4, 32'h11BB33DD, OKAY, 33);
            axi_write(8'h4, 32'h99887766, 4'b1010, 2'd2, 1);
            chk({30'd0, wr_resp}, {30'd0, OKAY}, 34);
            rd_chk(8'h4, 32'h99BB77DD, OKAY, 35);
            axi_write(8'h4, 32'hFFFFFFFF, 4'b0000, 2'd0, 2);
            chk({30'd0, wr_resp}, {30'd0, OKAY}, 36);
            rd_chk(8'h4, 32'h99BB77DD, OKAY, 37);
            axi_read(8'h4, 5);
            chk(rd_data, 32'h99BB77DD, 38);
            chk({30'd0, rd_resp}, {30'd0, OKAY}, 39);

            // COUNT is read only
            axi_write(8'h8, 32'h12345678, 4'hF, 2'd1, 2);
            chk({30'd0, wr_resp}, {30'd0, SLVERR}, 40);
            rd_chk(8'h8, 32'd0, OKAY, 41);

            // Unaligned addresses
            wr_chk(8'h5, 32'h00000000, 4'hF, SLVERR, 42);
            rd_chk(8'h4, 32'h99BB77DD, OKAY, 43);
            wr_chk(8'h1, 32'h00000007, 4'hF, SLVERR, 44);
            rd_chk(8'h0, 32'd0, OKAY, 45);
            rd_chk(8'h6, 32'd0, SLVERR, 46);
            rd_chk(8'h3, 32'd0, SLVERR, 47);

            // Offsets from 0x10 up are unmapped at ADDR_WIDTH 8
            if (sel8) begin
                wr_chk(8'h10, 32'h00000007, 4'hF, SLVERR, 50);
                rd_chk(8'h0, 32'd0, OKAY, 51);
                wr_chk(8'h14, 32'h00000000, 4'hF, SLVERR, 52);
                rd_chk(8'h4, 32'h99BB77DD, OKAY, 53);
                wr_chk(8'hFC, 32'h00000001, 4'hF, SLVERR, 54);
                rd_chk(8'h10, 32'd0, SLVERR, 55);
                rd_chk(8'h14, 32'd0, SLVERR, 56);
                rd_chk(8'h18, 32'd0, SLVERR, 57);
                rd_chk(8'h4C, 32'd0, SLVERR, 58);
                rd_chk(8'hF4, 32'd0, SLVERR, 59);
                rd_chk(8'hC, 32'd0, OKAY, 49);
            end

            // CTRL write without wstrb[0] changes nothing, answers OKAY
            wr_chk(8'h0, 32'h00000007, 4'b1110, OKAY, 60);
            rd_chk(8'h0, 32'd0, OKAY, 61);
            wait_cycles(5);
            rd_chk(8'h8, 32'd0, OKAY, 62);
            rd_chk(8'hC, 32'd0, OKAY, 63);
            chk({31'd0, irq_m}, 32'd0, 64);

            // One-shot, LOAD 5, timed; EN self-clears; no second interrupt
            wr_chk(8'h4, 32'd5, 4'hF, OKAY, 70);
            base = rises;
            wr_chk(8'h0, 32'h00000003, 4'h1, OKAY, 71);
            e = wr_edge;
            wait_until(e + 6);
            chk(rises - base, 32'd1, 72);
            chk(rise_edge, e + 5, 73);
            chk({31'd0, irq_m}, 32'd1, 74);
            rd_chk(8'h0, 32'h00000002, OKAY, 75);
            rd_chk(8'h8, 32'd0, OKAY, 76);
            rd_chk(8'hC, 32'd1, OKAY, 77);
            wait_cycles(20);
            chk(rises - base, 32'd1, 78);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 79);
            chk({31'd0, irq_m}, 32'd0, 80);
            rd_chk(8'hC, 32'd0, OKAY, 81);
            wait_cycles(20);
            chk(rises - base, 32'd1, 82);
            chk({31'd0, irq_m}, 32'd0, 83);
            rd_chk(8'h8, 32'd0, OKAY, 84);
            rd_chk(8'h0, 32'h00000002, OKAY, 85);

            // One-shot, LOAD 1 and LOAD 0: both end one edge after the start
            wr_chk(8'h4, 32'd1, 4'hF, OKAY, 90);
            base = rises;
            wr_chk(8'h0, 32'h00000003, 4'h1, OKAY, 91);
            e = wr_edge;
            wait_until(e + 3);
            chk(rises - base, 32'd1, 92);
            chk(rise_edge, e + 1, 93);
            rd_chk(8'h0, 32'h00000002, OKAY, 94);
            rd_chk(8'h8, 32'd0, OKAY, 95);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 96);
            wr_chk(8'h4, 32'd0, 4'hF, OKAY, 97);
            base = rises;
            wr_chk(8'h0, 32'h00000003, 4'h1, OKAY, 98);
            e = wr_edge;
            wait_until(e + 3);
            chk(rises - base, 32'd1, 99);
            chk(rise_edge, e + 1, 100);
            rd_chk(8'h0, 32'h00000002, OKAY, 101);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 102);

            // One-shot, LOAD 37, COUNT read while counting
            wr_chk(8'h4, 32'd37, 4'hF, OKAY, 110);
            base = rises;
            wr_chk(8'h0, 32'h00000003, 4'h1, OKAY, 111);
            e = wr_edge;
            axi_read(8'h8, 0);
            chk(rd_data, 37 - (rd_edge - 1 - e), 112);
            wait_until(e + 38);
            chk(rises - base, 32'd1, 113);
            chk(rise_edge, e + 37, 114);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 115);

            // IE written 1 on a pending expiry raises irq at once
            wr_chk(8'h4, 32'd3, 4'hF, OKAY, 120);
            base = rises;
            wr_chk(8'h0, 32'h00000001, 4'h1, OKAY, 121);
            e = wr_edge;
            wait_until(e + 10);
            chk(rises - base, 32'd0, 122);
            chk({31'd0, irq_m}, 32'd0, 123);
            rd_chk(8'hC, 32'd1, OKAY, 124);
            rd_chk(8'h0, 32'd0, OKAY, 125);
            wr_chk(8'h0, 32'h00000002, 4'h1, OKAY, 126);
            er = wr_edge;
            chk({31'd0, irq_m}, 32'd1, 127);
            chk(rise_edge, er, 128);
            chk(rises - base, 32'd1, 129);
            wr_chk(8'h0, 32'h00000000, 4'h1, OKAY, 130);
            chk({31'd0, irq_m}, 32'd0, 131);
            rd_chk(8'hC, 32'd1, OKAY, 132);
            wr_chk(8'hC, 32'h00000000, 4'h1, OKAY, 133);
            rd_chk(8'hC, 32'd1, OKAY, 134);
            wr_chk(8'hC, 32'h00000001, 4'hE, OKAY, 135);
            rd_chk(8'hC, 32'd1, OKAY, 136);
            wr_chk(8'hC, 32'h00000001, 4'h1, OKAY, 137);
            rd_chk(8'hC, 32'd0, OKAY, 138);

            // Periodic, LOAD 6, timed over several periods
            wr_chk(8'h4, 32'd6, 4'hF, OKAY, 140);
            base = rises;
            wr_chk(8'h0, 32'h00000007, 4'h1, OKAY, 141);
            e = wr_edge;
            wait_until(e + 7);
            chk(rises - base, 32'd1, 142);
            chk(rise_edge, e + 6, 143);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 144);
            chk(wr_edge, e + 8, 145);
            chk({31'd0, irq_m}, 32'd0, 146);
            wait_until(e + 13);
            chk(rises - base, 32'd2, 147);
            chk(rise_edge, e + 12, 148);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 149);
            axi_read(8'h8, 0);
            chk(rd_edge, e + 16, 150);
            chk(rd_data, 32'd3, 151);
            rd_chk(8'h0, 32'h00000007, OKAY, 152);
            wait_until(e + 19);
            chk(rises - base, 32'd3, 153);
            chk(rise_edge, e + 18, 154);
            // A clear on the edge a count ends: EXPIRED stays set
            wait_until(e + 23);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 155);
            chk(wr_edge, e + 24, 156);
            rd_chk(8'hC, 32'd1, OKAY, 157);
            chk({31'd0, irq_m}, 32'd1, 158);
            chk(rises - base, 32'd3, 159);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 160);
            chk(wr_edge, e + 28, 161);
            chk({31'd0, irq_m}, 32'd0, 162);
            wait_until(e + 31);
            chk(rises - base, 32'd4, 163);
            chk(rise_edge, e + 30, 164);
            wr_chk(8'h0, 32'h00000000, 4'h1, OKAY, 165);
            rd_chk(8'h8, 32'd4, OKAY, 166);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 167);

            // A stop freezes COUNT
            wr_chk(8'h4, 32'd100, 4'hF, OKAY, 170);
            base = rises;
            wr_chk(8'h0, 32'h00000003, 4'h1, OKAY, 171);
            e = wr_edge;
            wait_cycles(10);
            wr_chk(8'h0, 32'h00000002, 4'h1, OKAY, 172);
            es  = wr_edge;
            cnt = 100 - (es - e);
            rd_chk(8'h8, cnt, OKAY, 173);
            wait_cycles(15);
            rd_chk(8'h8, cnt, OKAY, 174);
            rd_chk(8'h0, 32'h00000002, OKAY, 175);
            rd_chk(8'hC, 32'd0, OKAY, 176);
            chk(rises - base, 32'd0, 177);

            // A restart while counting
            wr_chk(8'h4, 32'd10, 4'hF, OKAY, 180);
            base = rises;
            wr_chk(8'h0, 32'h00000003, 4'h1, OKAY, 181);
            e = wr_edge;
            wait_until(e + 4);
            wr_chk(8'h0, 32'h00000003, 4'h1, OKAY, 182);
            er = wr_edge;
            chk(er, e + 5, 183);
            wait_until(er + 11);
            chk(rises - base, 32'd1, 184);
            chk(rise_edge, er + 10, 185);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 186);

            // CTRL EN=1 on the edge a one-shot ends: restart wins, expiry kept
            wr_chk(8'h4, 32'd4, 4'hF, OKAY, 190);
            base = rises;
            wr_chk(8'h0, 32'h00000003, 4'h1, OKAY, 191);
            e = wr_edge;
            wait_until(e + 3);
            wr_chk(8'h0, 32'h00000003, 4'h1, OKAY, 192);
            chk(wr_edge, e + 4, 193);
            chk(rises - base, 32'd1, 194);
            chk(rise_edge, e + 4, 195);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 196);
            chk(wr_edge, e + 6, 197);
            chk({31'd0, irq_m}, 32'd0, 198);
            wait_until(e + 9);
            chk(rises - base, 32'd2, 199);
            chk(rise_edge, e + 8, 200);
            rd_chk(8'h0, 32'h00000002, OKAY, 201);
            rd_chk(8'h8, 32'd0, OKAY, 202);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 203);

            // CTRL EN=0 on the edge a periodic count ends: COUNT reloads, stops
            wr_chk(8'h4, 32'd4, 4'hF, OKAY, 210);
            base = rises;
            wr_chk(8'h0, 32'h00000007, 4'h1, OKAY, 211);
            e = wr_edge;
            wait_until(e + 3);
            wr_chk(8'h0, 32'h00000006, 4'h1, OKAY, 212);
            chk(wr_edge, e + 4, 213);
            rd_chk(8'h8, 32'd4, OKAY, 214);
            rd_chk(8'h0, 32'h00000006, OKAY, 215);
            rd_chk(8'hC, 32'd1, OKAY, 216);
            chk(rises - base, 32'd1, 217);
            chk(rise_edge, e + 4, 218);
            wait_cycles(10);
            rd_chk(8'h8, 32'd4, OKAY, 219);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 220);
            wr_chk(8'h0, 32'h00000000, 4'h1, OKAY, 221);

            // Periodic with LOAD 0: every edge ends a count, so a clear never wins
            wr_chk(8'h4, 32'd0, 4'hF, OKAY, 230);
            wr_chk(8'h0, 32'h00000005, 4'h1, OKAY, 231);
            wait_cycles(3);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 232);
            rd_chk(8'hC, 32'd1, OKAY, 233);
            rd_chk(8'h8, 32'd0, OKAY, 234);
            rd_chk(8'h0, 32'h00000005, OKAY, 235);
            wr_chk(8'h0, 32'h00000000, 4'h1, OKAY, 236);
            wr_chk(8'hC, 32'd1, 4'h1, OKAY, 237);
            rd_chk(8'hC, 32'd0, OKAY, 238);

            // Reset during a count
            wr_chk(8'h4, 32'd50, 4'hF, OKAY, 240);
            base = rises;
            wr_chk(8'h0, 32'h00000007, 4'h1, OKAY, 241);
            wait_cycles(10);
            do_reset;
            chk({31'd0, irq_m}, 32'd0, 242);
            rd_chk(8'h0, 32'd0, OKAY, 243);
            rd_chk(8'h4, 32'd0, OKAY, 244);
            rd_chk(8'h8, 32'd0, OKAY, 245);
            rd_chk(8'hC, 32'd0, OKAY, 246);
            wait_cycles(70);
            chk(rises - base, 32'd0, 247);
            rd_chk(8'hC, 32'd0, OKAY, 248);

            // Reset clears a held write address
            awaddr_r  = 8'h0;
            awvalid_r = 1'b1;
            chk({31'd0, awready_m}, 32'd1, 250);
            @(posedge clk);
            @(negedge clk);
            awvalid_r = 1'b0;
            chk({31'd0, awready_m}, 32'd0, 251);
            do_reset;
            chk({31'd0, awready_m}, 32'd1, 252);
            chk({31'd0, wready_m},  32'd1, 253);
            chk({31'd0, bvalid_m},  32'd0, 254);
            wr_chk(8'h4, 32'h0000005A, 4'hF, OKAY, 255);
            rd_chk(8'h4, 32'h0000005A, OKAY, 256);
            rd_chk(8'h0, 32'd0, OKAY, 257);
            chk({31'd0, irq_m}, 32'd0, 258);
        end
    endtask

    initial begin
        nonce = {8*64{1'b0}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
            nonce = {8*64{1'b0}};
        end
        @(negedge clk);
        sel8 = 1'b0;
        run_all;
        sel8 = 1'b1;
        run_all;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #5000000;
        $error("watchdog: simulation did not finish");
        failed = failed + 1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
